class Solution {
  public long minimumOperations(int[] nums, int[] target) {
    long answer = 0;
    long previous = 0;
    for (int i = 0; i < nums.length; i++) {
      long current = (long) target[i] - nums[i];
      if ((current >= 0) != (previous >= 0)) {
        answer += Math.abs(current);
      } else {
        answer += Math.max(0L, Math.abs(current) - Math.abs(previous));
      }
      previous = current;
    }
    return answer;
  }
}
